import type { CartLine } from '#shared/types/cart'

export interface Order {
  id: string
  lines: CartLine[]
  /** Amounts in the server money format, e.g. `19.99 USD`. */
  subtotal: string
  discount: string
  total: string
}

import type { CartLine } from '#shared/types/cart'
import type { Order } from '#shared/types/order'

/** Orders placed since the server started. Kept in memory only. */
const orders = new Map<string, Order>()

/** Stores an order with the amounts the server charges, computed exactly like the quote API. */
export function saveOrder(lines: CartLine[], code?: string): Order {
  const order: Order = {
    id: crypto.randomUUID(),
    lines: lines.map(line => ({ slug: line.slug, qty: line.qty })),
    ...computeQuote(lines, code),
  }
  orders.set(order.id, order)
  return order
}

export function findOrder(id: string): Order | undefined {
  return orders.get(id)
}

import type { CartLine } from '#shared/types/cart'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: CartLine[], code?: unknown }>(event)
  const lines = body?.lines
  const valid = Array.isArray(lines)
    && lines.length > 0
    && lines.every(line => findProduct(line.slug) && Number.isInteger(line.qty) && line.qty > 0)
  if (!valid)
    throw createError({ statusCode: 400, statusMessage: 'Invalid order lines' })

  const code = typeof body?.code === 'string' ? body.code : undefined
  const { id, subtotal, discount, total } = saveOrder(lines, code)
  return { id, subtotal, discount, total }
})

export default defineEventHandler((event) => {
  const order = findOrder(getRouterParam(event, 'id') ?? '')
  if (!order)
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  return order
})

